        'Втори принцип на Нютон (Основен закон на динамиката): Ускорението (a), което получава едно тяло, е правопропорционално на равнодействащата сила (F), приложена върху него, и обратнопропорционално на масата му (m): a = F / m или F = m·a. Единица за сила в SI: 1 Нютон (1 N = 1 kg·m/s²).',
