    originalNoteExcerpt: 'Балкански съюз (1912): договор България–Сърбия със „спорна“ и „безспорна“ зона в Македония. Първа балканска война (октомври 1912 – май 1913): Лозенград, Люлебургаз–Бунархисар, превземането на Одринската крепост (13 март 1913, ген. Георги Вазов), мидия–Енос (Лондонски договор, 17 май 1913). Междусъюзническа война (16 юни 1913 — „престъпното безумие“): Букурещки договор (28 юли 1913) и Цариградски договор — Първа национална катастрофа. ПСВ за България (октомври 1915 – септември 1918): Тутракан и Добрич (ген. Колев, 1916), Дойранската епопея (ген. Владимир Вазов, 1918), Солунско примирие, Владайско въстание и Ньойски договор (27 ноември 1919) — Втора национална катастрофа.',
