        'Първа балканска война (5 октомври 1912 – 17 май 1913 г.): Българската армия понася основната тежест на войната на Тракийския фронт (победите при Лозенград и Люлебургаз–Бунархисар). На 13 март 1913 г. Втора българска армия (ген. Никола Иванов и ген. Георги Вазов) превзема с щурм смятаната за непревземаема Одринска крепост, а на 16 октомври 1912 г. Радул Милков и Продан Таракчиев извършват първия боен полет в Европа. С Лондонския мирен договор (17 май 1913 г.) Турция отстъпва всички земи на запад от линията Мидия – Енос.',
        'Междусъюзническа (Втора балканска) война и Първа национална катастрофа (1913 г.): Сърбия и Гърция отказват да напуснат окупираните части на Македония и сключват таен антибългарски съюз. На 16 юни 1913 г. цар Фердинанд и ген. Михаил Савов без решение на правителството дават заповед за атака („престъпното безумие“). Срещу България се включват и Румъния (нахлува в Южна Добруджа) и Османската империя (завзема Източна Тракия). По Букурещкия (28 юли 1913) и Цариградския договор България губи Вардарска и Егейска Македония, Южна Добруджа и Одринска Тракия, запазвайки само Пиринския край и излаза на Бяло море при Западна Тракия (Дедеагач).',
        'България в Първата световна война (14 октомври 1915 – 29 септември 1918 г.): Кабинетът на д-р Васил Радославов присъединява България към Централните сили (Германия и Австро-Унгария). Българската армия разгромява сръбските сили в Македония (1915), освобождава Южна Добруджа с блестящия щурм на Тутраканската крепост (5–6 септември 1916 г.) и конницата на ген. Иван Колев при Добрич, а на Южния фронт Девета плевенска дивизия на ген. Владимир Вазов печели легендарната отбранителна победа при Дойран (септември 1918 г.).',
