      'Немски език (Deutsch B1/B2): Падежна система (Nominativ, Akkusativ, Dativ, Genitiv), словоред в подчинено изречение с weil, dass, obwohl (глаголът отива на края), Perfekt (haben/sein + Partizip II), Passiv (werden + Partizip II) и Konjunktiv II. Френски език (Français B1/B2): Passé composé vs. Imparfait, Subjonctif présent, условни изречения с „si“. Испански език (Español B1/B2): Разлика между ser и estar, Pretérito indefinido vs. imperfecto, Subjuntivo и аргументативно есе за ДЗИ.',
