        'Корабоводене и Морско/Речно дело (Специалност „Корабоводене“ / „Корабни машини и механизми“): Условие за плаваемост по закона на Архимед (P = γ · V, където V е обемът на водоизместването). Устойчивостта (остойчивостта) на кораба зависи от метацентричната височина h (метацентърът M трябва да лежи над центъра на тежестта G: h = ZM - ZG > 0). Една морска миля (NM) = 1 852 m (дължината на 1 дъгова минута от земния меридиан); 1 възел (knot) = 1 морска миля в час (1.852 km/h).',
        'Железопътна техника и осигурителни инсталации: Електрическа тяга (контактна мрежа в България — 25 kV, 50 Hz променлив ток), спирачен път, автоматична локомотивна сигнализация (АЛС) и европейска система за управление на влаковете (ERTMS / ETCS).',
