        'Уравнение на окръжност и Криви от втора степен (Конични сечения): 1) Окръжност с център C(x₀, y₀) и радиус R: (x - x₀)² + (y - y₀)² = R²; 2) Канонично уравнение на елипса: x²/a² + y²/b² = 1 (с фокуси F₁(-c, 0) и F₂(c, 0), където c² = a² - b²); 3) Канонично уравнение на хипербола: x²/a² - y²/b² = 1 (където c² = a² + b² и асимптоти y = ±(b/a)x); 4) Канонично уравнение на парабола: y² = 2px.'
